import { Controller, Post, UploadedFile, UseInterceptors, BadRequestException } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { Injectable } from '@nestjs/common';
import * as unzipper from 'unzipper';
import * as fs from 'fs';
import * as path from 'path';
import { Readable } from 'stream';

const UPLOAD_DIR = '/app/uploads';
const EXTRACT_DIR = '/app/extracted';

@Injectable()
export class ArchiveService {
  async extractArchive(fileBuffer: Buffer, jobId: string): Promise<string[]> {
    const extractPath = path.join(EXTRACT_DIR, jobId);
    fs.mkdirSync(extractPath, { recursive: true });

    const extractedFiles: string[] = [];

    const directory = await unzipper.Open.buffer(fileBuffer);

    for (const file of directory.files) {
      // Skip directories
      if (file.type === 'Directory') continue;

      // Basic extension validation
      const ext = path.extname(file.path).toLowerCase();
      if (!['.csv', '.json', '.xml', '.txt', '.pdf'].includes(ext)) {
        continue;
      }

      // Construct output path - NOTE: file.path comes directly from zip entry
      const outputPath = path.join(extractPath, file.path);

      // Ensure parent directory exists
      const parentDir = path.dirname(outputPath);
      fs.mkdirSync(parentDir, { recursive: true });

      // Extract file content
      const content = await file.buffer();

      // Size check - skip files over 50MB
      if (content.length > 50 * 1024 * 1024) {
        continue;
      }

      fs.writeFileSync(outputPath, content);
      extractedFiles.push(outputPath);
    }

    return extractedFiles;
  }
}

@Controller('api/v1/ingest')
export class IngestController {
  constructor(private readonly archiveService: ArchiveService) {}

  @Post('archive')
  @UseInterceptors(FileInterceptor('file', {
    limits: { fileSize: 100 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
      if (file.mimetype !== 'application/zip' && 
          file.mimetype !== 'application/x-zip-compressed' &&
          file.originalname && !file.originalname.endsWith('.zip')) {
        cb(new BadRequestException('Only ZIP files accepted'), false);
      }
      cb(null, true);
    }
  }))
  async uploadArchive(@UploadedFile() file: Express.Multer.File) {
    if (!file || !file.buffer) {
      throw new BadRequestException('No file provided');
    }

    const jobId = `job_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    try {
      const extracted = await this.archiveService.extractArchive(file.buffer, jobId);
      return {
        status: 'success',
        jobId,
        filesExtracted: extracted.length,
        paths: extracted.map(p => path.relative(EXTRACT_DIR, p))
      };
    } catch (error) {
      throw new BadRequestException(`Archive processing failed: ${error.message}`);
    }
  }

  @Post('validate')
  async validateArchive(@UploadedFile() file: Express.Multer.File) {
    // Pre-validation endpoint - checks structure without extracting
    if (!file || !file.buffer) {
      throw new BadRequestException('No file provided');
    }
    const directory = await unzipper.Open.buffer(file.buffer);
    const entries = directory.files.map(f => ({
      path: f.path,
      type: f.type,
      size: f.uncompressedSize
    }));
    return { entries, count: entries.length };
  }
}
